command:
// Independent RULE-04 auditor probe. Expectations come from the CR2.3 text
// (8.16 Adventurous, 1.13 ink drop counters, 8.14 Vanish, 7.7.3.1 bag), not
// from engine output. It drives the actual compiled pinned runtime through the
// test-only bridge and checks rejected commands leave state untouched.
import assert from 'node:assert/strict';
const { withScenarioRuntime } = await import('./scripts/rules/scenario-build.mjs');
const fill = cards => { for (const o of ['p1', 'p2']) if (!cards.some(c => c.owner === o && c.zone === 'deck')) cards.push(...[0, 1, 2].map(i => ({ id: `${o}-deck-${i}`, owner: o, zone: 'deck' }))); return cards; };
const results = [], observations = [];
await withScenarioRuntime(async ({ createScenarioRuntime, assertScenarioState }) => {
  function run(name, cards, extra, body) {
    const fixture = { cards: fill(cards), ...extra }, ids = fixture.cards.map(c => c.id);
    const m = createScenarioRuntime(fixture);
    const step = (actor, move, args, expect) => {
      const before = m.snapshot(), r = m.submit(actor, move, args);
      if (expect !== undefined) assert.equal(r.accepted, expect, `${name}: ${move} by ${actor} -> ${r.code}`);
      if (!r.accepted) assert.deepEqual(m.snapshot(), before, `${name}: rejected ${move} mutated state`);
      assertScenarioState(m.snapshot(), ids);
      return r;
    };
    body({ step, s: () => m.snapshot(), legal: m.legal });
    results.push(name);
  }
  const adv = { type: 'keyword', keyword: 'Adventurous' };
  // 8.16.3 "You can't declare the end of your turn": only the controller is bound.
  run('A1 opposing Adventurous does not bind the active player', [{ id: 'theirs', owner: 'p2', zone: 'play', abilities: [adv] }], {},
    ({ step, s }) => { step('p1', 'passTurn', {}, true); assert.equal(s().ctx.status.turn, 2); });
  // 8.16.3 "... if this character is ready and can quest": a can't-quest restriction lifts the obligation.
  run('A2 Adventurous that cannot quest does not block ending the turn', [{ id: 'hero', owner: 'p1', zone: 'play', abilities: [adv], meta: { temporaryRestrictions: { 'cant-quest': 1 } } }], {},
    ({ step }) => { step('p1', 'quest', { cardId: 'hero' }, false); step('p1', 'passTurn', {}, true); });
  // Every ready Adventurous character that can quest binds separately.
  run('A3 each Adventurous character must quest before the turn can end', [
    { id: 'a', owner: 'p1', zone: 'play', abilities: [adv] }, { id: 'b', owner: 'p1', zone: 'play', abilities: [adv] }], {},
  ({ step, s }) => {
    step('p1', 'passTurn', {}, false); step('p1', 'quest', { cardId: 'a' }, true);
    step('p1', 'passTurn', {}, false); step('p1', 'quest', { cardId: 'b' }, true);
    assert.equal(s().G.lore.p1, 2); step('p1', 'passTurn', {}, true);
  });
  // 8.16.2 restricts challenging, not being challenged.
  run('A4 an exerted Adventurous character can still be challenged', [
    { id: 'attacker', owner: 'p1', zone: 'play', strength: 3 },
    { id: 'target', owner: 'p2', zone: 'play', abilities: [adv], willpower: 5, meta: { state: 'exerted' } }], {},
  ({ step, s }) => { step('p1', 'challenge', { attackerId: 'attacker', defenderId: 'target' }, true); assert.equal(s().ctx.zones.private.cardMeta.target.damage, 3); });
  run('A5 legal moves omit an Adventurous challenge and the blocked end of turn', [
    { id: 'hero', owner: 'p1', zone: 'play', abilities: [adv, { type: 'keyword', keyword: 'Rush' }] },
    { id: 'enemy', owner: 'p2', zone: 'play', meta: { state: 'exerted' } }], {},
  ({ legal, step }) => {
    // Enumeration is move-name level; like inherited Reckless/must-quest it still
    // names passTurn, so the end-of-turn obligation is checked by submission.
    const names = legal('p1');
    assert.ok(names.includes('quest'), 'quest should be enumerated');
    assert.ok(!names.includes('challenge'), 'challenge must not be enumerated: ' + names.join(','));
    step('p1', 'challenge', { attackerId: 'hero', defenderId: 'enemy' }, false);
    assert.equal(step('p1', 'passTurn', {}, false).code, 'PASS_TURN_ADVENTUROUS_QUEST_REQUIRED');
  });
  // 1.13.1.2: counters pay "that much ink toward any ink cost".
  run('B1 counters alone pay a full character cost', [{ id: 'hero', owner: 'p1', zone: 'hand', cost: 3 }], { inkDropCounters: { p1: 3, p2: 4 } },
    ({ step, s }) => { step('p1', 'playCard', { cardId: 'hero', cost: 'standard' }, true); assert.equal(s().G.inkDropCounters.p1, 0); assert.equal(s().G.inkDropCounters.p2, 4); assert.equal(s().ctx.zones.private.cardIndex.hero.zoneKey, 'play:p1'); });
  run('B2 default payment exerts ready ink before removing counters', [
    { id: 'hero', owner: 'p1', zone: 'hand', cost: 3 }, { id: 'i1', owner: 'p1', zone: 'inkwell' }, { id: 'i2', owner: 'p1', zone: 'inkwell' }], { inkDropCounters: { p1: 2 } },
  ({ step, s }) => { step('p1', 'playCard', { cardId: 'hero', cost: 'standard' }, true); const z = s().ctx.zones.private.cardMeta; assert.equal(z.i1.state, 'exerted'); assert.equal(z.i2.state, 'exerted'); assert.equal(s().G.inkDropCounters.p1, 1); });
  run('B3 selecting more counters than owned is rejected', [
    { id: 'hero', owner: 'p1', zone: 'hand', cost: 2 }, { id: 'i1', owner: 'p1', zone: 'inkwell' }, { id: 'i2', owner: 'p1', zone: 'inkwell' }], { inkDropCounters: { p1: 1 } },
  ({ step }) => { step('p1', 'playCard', { cardId: 'hero', cost: 'standard', inkDropCounters: 2 }, false); });
  run('B4 selecting more counters than the cost is rejected', [{ id: 'hero', owner: 'p1', zone: 'hand', cost: 1 }], { inkDropCounters: { p1: 2 } },
    ({ step }) => { step('p1', 'playCard', { cardId: 'hero', cost: 'standard', inkDropCounters: 2 }, false); });
  // 1.13.2: counters are not cards; inking a card leaves the pool alone.
  run('B5 inking a card neither creates nor spends counters', [{ id: 'gem', owner: 'p1', zone: 'hand' }], { inkDropCounters: { p1: 2 } },
    ({ step, s }) => { step('p1', 'putCardIntoInkwell', { cardId: 'gem' }, true); assert.equal(s().G.inkDropCounters.p1, 2); assert.equal(s().ctx.zones.private.zoneCards['inkwell:p1'].length, 1); });
  run('B6 a card affordable only with counters is enumerated as playable', [{ id: 'hero', owner: 'p1', zone: 'hand', cost: 2 }], { inkDropCounters: { p1: 2 } },
    ({ legal }) => { assert.ok(legal('p1').includes('playCard'), 'playCard should be legal with counters'); });
  run('B6b one counter short of the cost is not enumerated as playable', [{ id: 'hero', owner: 'p1', zone: 'hand', cost: 2 }], { inkDropCounters: { p1: 1 } },
    ({ legal, step }) => { assert.ok(!legal('p1').includes('playCard'), 'playCard must not be legal one counter short'); step('p1', 'playCard', { cardId: 'hero', cost: 'standard' }, false); });
  run('B7 counters cannot be spent on a cost with no ink component', [
    { id: 'song', owner: 'p1', zone: 'hand', cardType: 'action', actionSubtype: 'song', cost: 2, abilities: [{ type: 'action', effect: { type: 'gain-lore', amount: 1, target: 'CONTROLLER' } }] },
    { id: 'singer', owner: 'p1', zone: 'play', cost: 3 }], { inkDropCounters: { p1: 2 } },
  ({ step, s }) => { step('p1', 'playCard', { cardId: 'song', cost: 'sing', singerId: 'singer', inkDropCounters: 1 }); assert.equal(s().G.inkDropCounters.p1, 2); });
  run('B8 counters persist through the opponent turn and both ready steps', [{ id: 'hero', owner: 'p1', zone: 'play', meta: { state: 'exerted' } }], { inkDropCounters: { p1: 2, p2: 1 } },
    ({ step, s }) => { step('p1', 'passTurn', {}, true); step('p2', 'passTurn', {}, true); assert.deepEqual(s().G.inkDropCounters, { p1: 2, p2: 1 }); });
  // 8.14.1: Vanish needs an opponent's action to *choose* the character.
  run('C1 an unchosen opposing action effect does not trigger Vanish', [
    { id: 'wave', owner: 'p1', zone: 'hand', cardType: 'action', cost: 0, abilities: [{ type: 'action', effect: { type: 'deal-damage', amount: 1, target: 'ALL_OPPOSING_CHARACTERS' } }] },
    { id: 'ghost', owner: 'p2', zone: 'play', abilities: [{ type: 'keyword', keyword: 'Vanish' }] }], {},
  ({ step, s }) => { step('p1', 'playCard', { cardId: 'wave', cost: 'standard' }, true); assert.equal(s().ctx.zones.private.cardMeta.ghost.damage, 1); assert.equal(s().G.triggeredAbilities?.bag?.items?.length ?? 0, 0); assert.equal(s().ctx.zones.private.cardIndex.ghost.zoneKey, 'play:p2'); });
  // 7.7.3.1: the trigger belongs to the player whose card generated it.
  run('C2 only the Vanish controller resolves its bag entry', [
    { id: 'zap', owner: 'p1', zone: 'hand', cardType: 'action', cost: 0, abilities: [{ type: 'action', effect: { type: 'deal-damage', amount: 1, target: 'CHOSEN_CHARACTER' } }] },
    { id: 'ghost', owner: 'p2', zone: 'play', abilities: [{ type: 'keyword', keyword: 'Vanish' }] }], {},
  ({ step, s }) => {
    step('p1', 'playCard', { cardId: 'zap', cost: 'standard', targets: ['ghost'] }, true);
    const items = s().G.triggeredAbilities.bag.items; assert.equal(items.length, 1);
    step('p1', 'resolveBag', { bagId: items[0].id, params: {} }, false);
    step('p1', 'passTurn', {}, false);
    step('p2', 'resolveBag', { bagId: items[0].id, params: {} }, true);
    assert.equal(s().ctx.zones.private.cardIndex.ghost.zoneKey, 'discard:p2');
  });
  // Characterization only (not a pass condition): a static lose-keyword effect.
  for (const target of ['SELF', 'ALL_OPPOSING_CHARACTERS']) {
    const cards = () => fill([
      { id: 'hero', owner: 'p1', zone: 'play', abilities: [adv, ...(target === 'SELF' ? [{ type: 'static', effect: { type: 'lose-keyword', keyword: 'Adventurous', target } }] : [])] },
      { id: 'enemy', owner: 'p2', zone: 'play', meta: { state: 'exerted' }, abilities: target === 'SELF' ? [] : [{ type: 'static', effect: { type: 'lose-keyword', keyword: 'Adventurous', target } }] }]);
    const challenge = createScenarioRuntime({ cards: cards() }).submit('p1', 'challenge', { attackerId: 'hero', defenderId: 'enemy' });
    const pass = createScenarioRuntime({ cards: cards() }).submit('p1', 'passTurn', {});
    observations.push({ staticLoseAdventurous: target, challengeAccepted: challenge.accepted, passTurnAccepted: pass.accepted, passTurnCode: pass.code });
  }
});
console.log(JSON.stringify({ cases: results.length, names: results }));
console.log('OBSERVED ' + JSON.stringify(observations) + ' -- after a static lose-keyword effect the challenge check no longer sees Adventurous, but the end-of-turn check still requires a quest (static losses are not consulted there); untested by the RULE-04 suite, follow-up before any Adventurous card admission');
console.log('PASS independent RULE-04 auditor probe: Adventurous controller/ability/enumeration, ink-drop payment/ownership/persistence, Vanish choice and bag ownership');
